export const getDynamicSyncStats = (companyList: Company[] = KOLKATA_COMPANIES): SyncStats => {
  const companiesTracked = companyList.length;
  const companiesWithActiveJobs = companyList.filter(c => c.jobs && c.jobs.length > 0 && c.hiringStatus === 'hiring').length;
  const activeJobsDetected = companyList.reduce((acc, c) => acc + (c.jobs ? c.jobs.length : 0), 0);
  const fresherOpportunities = companyList.reduce((acc, c) => acc + (c.jobs ? c.jobs.filter(j => j.isFresherEligible).length : 0), 0);
  const verifiedLocationsCount = companyList.reduce((acc, c) => acc + (c.locations ? c.locations.length : 0), 0);

  return {
    companiesTracked,
    companiesWithActiveJobs,
    activeJobsDetected,
    fresherOpportunities,
    verifiedLocationsCount,
    lastSyncTimestamp: new Date().toISOString(),
    dataFreshnessString: 'Verified just now (Live Dynamic Sync)',
  };
};

export const INITIAL_SYNC_STATS: SyncStats = getDynamicSyncStats(KOLKATA_COMPANIES);

